    # rectangular 5 object, typically central
    hh=rng.randint(2,max(2,min(7,H//3))); ww=rng.randint(2,max(2,min(7,W//3)))
    r0=rng.randint(1,H-hh-2); c0=rng.randint(1,W-ww-2)
    for r in range(r0,r0+hh):
