            c=rng.randint(c0,c0+ww-1); r=rng.choice(list(range(0,r0))+list(range(r0+hh,H)))
        else:
            r=rng.randint(r0,r0+hh-1); c=r=rng.choice(list(range(0,c0))+list(range(c0+ww,W))) if False else (r, rng.choice(list(range(0,c0))+list(range(c0+ww,W))))
        if (r,c) not in used and g[r][c]==6: g[r][c]=8; used.add((r,c))
    for _ in range(n-len(used)):
        for __ in range(20):
            r,c=rng.randrange(H),rng.randrange(W)
            if g[r][c]==6 and (r,c) not in used: break
        g[r][c]=8; used.add((r,c))
    return g"}

